class Solution {
public:
    int longestPalindromeSubseq(string s) {
        int n = s.size();
        if (n < 2) return 0;
        vector<vector<array<int, 26>>> dp(n, vector<array<int, 26>>(n));
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len <= n; ++i) {
                int j = i + len - 1;
                for (int c = 0; c < 26; ++c) {
                    dp[i][j][c] = max(dp[i + 1][j][c], dp[i][j - 1][c]);
                }
                if (s[i] == s[j]) {
                    int c = s[i] - 'a';
                    int best = 0;
                    if (len > 2) {
                        for (int other = 0; other < 26; ++other) {
                            if (other != c) best = max(best, dp[i + 1][j - 1][other]);
                        }
                    }
                    dp[i][j][c] = max(dp[i][j][c], 2 + best);
                }
            }
        }
        int answer = 0;
        for (int x : dp[0][n - 1]) answer = max(answer, x);
        return answer;
    }
};
